// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;

    // IAccessControl interface id computed locally (xor of its function selectors)
    bytes4 constant IACCESS_ID =
        bytes4(keccak256("hasRole(bytes32,address)")) ^
        bytes4(keccak256("getRoleAdmin(bytes32)")) ^
        bytes4(keccak256("grantRole(bytes32,address)")) ^
        bytes4(keccak256("revokeRole(bytes32,address)")) ^
        bytes4(keccak256("renounceRole(bytes32,address)"));

    // IERC165 interface id computed locally
    bytes4 constant IERC165_ID = bytes4(keccak256("supportsInterface(bytes4)"));

    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }

    function testFuzz_property(bytes4 id) public {
        bool supported = c.supportsInterface(id);
        bool expected = (id == IACCESS_ID) || (id == IERC165_ID);
        assertTrue(supported == expected, "supportsInterface must report only IAccessControl and IERC165");
    }
}
